[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (P) at (0,0); \coordinate (R) at (5,0); \coordinate (Q) at (2,3); \coordinate (D) at (2,0);
\draw (P)--(R)--(Q)--cycle;
\draw[dashed] (Q)--(D);
\draw (2,0.25)--(2.25,0.25)--(2.25,0);
\path (P) node[below left] {$P$} (R) node[below right] {$R$} (Q) node[above] {$Q$} (D) node[below] {$D$};
\path (3.5,1.5) node[above right] {$p$} (2.5,0) node[below,yshift=-5mm] {$q$} (2,1.5) node[left] {$h$};
\end{tikzpicture}
[/tikz]
For acute $R$, right-angled triangle $QDR$ gives
$\begin{aligned}\sin R&=\frac{h}{p}\\h&=p\sin R.\end{aligned}$
Using base $PR=q$,
$\begin{aligned}K&=\frac12qh\\&=\frac12q(p\sin R)\\&=\frac12pq\sin R.\end{aligned}$
If $R$ is obtuse, $D$ lies beyond $R$ on $PR$ extended. The angle in the exterior right triangle is $180^\circ-R$, so
$\begin{aligned}h&=p\sin(180^\circ-R)\\&=p\sin R.\end{aligned}$
The same base and perpendicular height therefore give $K=\frac12pq\sin R$.

[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (P) at (0,0); \coordinate (Q) at (5,0); \coordinate (R) at (2,3); \coordinate (D) at (2,0);
\draw (P)--(Q)--(R)--cycle; \draw[dashed] (R)--(D);
\draw (2,0.25)--(2.25,0.25)--(2.25,0);
\path (P) node[below left] {$P$} (Q) node[below right] {$Q$} (R) node[above] {$R$} (D) node[below] {$D$};
\path (1,1.5) node[above left] {$q$} (3.5,1.5) node[above right] {$p$} (2,1.5) node[left] {$h$} (2.5,0) node[below,yshift=-5mm] {$r$};
\end{tikzpicture}
[/tikz]
The two right triangles give $h=q\sin P$ and $h=p\sin Q$. Equating these and dividing by $\sin P\sin Q$ gives
$\begin{aligned}q\sin P&=p\sin Q\\\frac{q\sin P}{\sin P\sin Q}&=\frac{p\sin Q}{\sin P\sin Q}\\\frac{q}{\sin Q}&=\frac{p}{\sin P}.\end{aligned}$
An altitude from $P$ to $QR$ similarly gives $r\sin Q=q\sin R$, hence $\frac{q}{\sin Q}=\frac{r}{\sin R}$. Together,
$\frac{p}{\sin P}=\frac{q}{\sin Q}=\frac{r}{\sin R}$.
Alternatively, divide $q\sin P=p\sin Q$ by $pq$ to obtain $\frac{\sin P}{p}=\frac{\sin Q}{q}$. Applying the same step to the other pair gives
$\frac{\sin P}{p}=\frac{\sin Q}{q}=\frac{\sin R}{r}$.
When $P=90^\circ$, $p$ is the hypotenuse and $\sin P=1$:
$\begin{aligned}p&=\frac{q}{\sin Q}\\p\sin Q&=q\\\sin Q&=\frac{q}{p}.\end{aligned}$

[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (P) at (0,0); \coordinate (Q) at (5,0); \coordinate (R) at (2,3); \coordinate (D) at (2,0);
\draw (P)--(Q)--(R)--cycle; \draw[dashed] (R)--(D);
\draw (2,0.25)--(2.25,0.25)--(2.25,0);
\path (P) node[below left] {$P$} (Q) node[below right] {$Q$} (R) node[above] {$R$} (D) node[below,yshift=-5mm] {$D$};
\path (1,1.5) node[above left] {$q$} (3.5,1.5) node[above right] {$p$} (2,1.5) node[left] {$h$};
\path (1,0) node[below] {$x$} (3.5,0) node[below] {$r-x$};
\end{tikzpicture}
[/tikz]
In right-angled triangle $PRD$,
$\begin{aligned}\cos P&=\frac{x}{q}\\x&=q\cos P,\\\sin P&=\frac{h}{q}\\h&=q\sin P.\end{aligned}$
Pythagoras in triangle $QRD$ gives
$\begin{aligned}p^2&=h^2+(r-x)^2\\&=(q\sin P)^2+(r-q\cos P)^2\\&=q^2\sin^2P+r^2-2qr\cos P+q^2\cos^2P\\&=q^2(\sin^2P+\cos^2P)+r^2-2qr\cos P\\&=q^2+r^2-2qr\cos P.\end{aligned}$
The identity $\sin^2P+\cos^2P=1$ combines the two squared trigonometric terms into $q^2$.
Rearranging,
$\begin{aligned}2qr\cos P&=q^2+r^2-p^2\\\cos P&=\frac{q^2+r^2-p^2}{2qr}.\end{aligned}$

[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (D) at (0,0); \coordinate (P) at (2,0); \coordinate (Q) at (6,0); \coordinate (R) at (0,3);
\draw (P)--(Q)--(R)--cycle; \draw[dashed] (D)--(P) (R)--(D);
\draw (0,0.25)--(0.25,0.25)--(0.25,0);
\path (D) node[below left] {$D$} (P) node[below] {$P$} (Q) node[below right] {$Q$} (R) node[above] {$R$};
\path (1,1.5) node[below left] {$q$} (3,1.5) node[above right] {$p$} (0,1.5) node[left] {$h$};
\end{tikzpicture}
[/tikz]
Since $PD$ and $PQ$ point in opposite directions, $\angle RPD=180^\circ-P$.
In right-angled triangle $RPD$,
$\begin{aligned}h&=q\sin(180^\circ-P)\\&=q\sin P.\end{aligned}$
In right-angled triangle $RQD$, $h=p\sin Q$. Therefore,
$\begin{aligned}q\sin P&=p\sin Q\\\frac{q\sin P}{\sin P\sin Q}&=\frac{p\sin Q}{\sin P\sin Q}\\\frac{q}{\sin Q}&=\frac{p}{\sin P}.\end{aligned}$
The supplementary sine identity preserves the altitude expression even though the altitude lies outside the triangle.

[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (D) at (0,0); \coordinate (P) at (2,0); \coordinate (Q) at (6,0); \coordinate (R) at (0,3);
\draw (P)--(Q)--(R)--cycle; \draw[dashed] (D)--(P) (R)--(D);
\draw (0,0.25)--(0.25,0.25)--(0.25,0);
\path (D) node[below left] {$D$} (P) node[below,yshift=-5mm] {$P$} (Q) node[below right] {$Q$} (R) node[above] {$R$};
\path (1,0) node[below] {$d$} (4,0) node[below] {$r$} (0,1.5) node[left] {$h$};
\path (1,1.5) node[below left] {$q$} (3,1.5) node[above right] {$p$};
\end{tikzpicture}
[/tikz]
In right-angled triangle $RPD$,
$\begin{aligned}d&=q\cos(180^\circ-P)\\&=-q\cos P.\end{aligned}$
Pythagoras also gives $h^2+d^2=q^2$. Since $QD=r+d$, Pythagoras in triangle $RQD$ gives
$\begin{aligned}p^2&=h^2+(r+d)^2\\&=(h^2+d^2)+r^2+2rd\\&=q^2+r^2+2r(-q\cos P)\\&=q^2+r^2-2qr\cos P.\end{aligned}$
For acute $P$ with an interior altitude foot, the base segment is $r-q\cos P$. Here it is $r+d=r-q\cos P$ as well, so both constructions yield the same formula.
Because $P$ is obtuse, $\cos P<0$. Thus $-2qr\cos P>0$ and $p^2>q^2+r^2$.

[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\coordinate (R) at (0,0); \coordinate (Q) at (5,0); \coordinate (P) at (2,3); \coordinate (D) at (2,0);
\draw[->] (-0.5,0)--(6,0); \draw[->] (0,-0.5)--(0,4);
\draw (R)--(P)--(Q); \draw[dashed] (P)--(D);
\draw (2,0.25)--(2.25,0.25)--(2.25,0);
\path (R) node[below left] {$R(0,0)$} (Q) node[below] {$Q(p,0)$} (P) node[above] {$P(q\cos R,q\sin R)$};
\path (1,1.5) node[above left] {$q$} (3.5,1.5) node[above right] {$r$} (6,0) node[right] {$x$} (0,4) node[above] {$y$};
\end{tikzpicture}
[/tikz]
The horizontal and vertical components of $RP$ are $q\cos R$ and $q\sin R$, so $P=(q\cos R,q\sin R)$.
Using the distance formula between $P$ and $Q$,
$\begin{aligned}r^2&=(p-q\cos R)^2+(0-q\sin R)^2\\&=p^2-2pq\cos R+q^2\cos^2R+q^2\sin^2R\\&=p^2-2pq\cos R+q^2(\cos^2R+\sin^2R)\\&=p^2+q^2-2pq\cos R.\end{aligned}$
For obtuse $R$, the horizontal coordinate $q\cos R$ is negative. The same distance formula and identity still apply.

